<?php

declare(strict_types=1);

// Serves uploaded photos (gallery, item photos) from storage/uploads, outside the web root –
// the website's copy of order/media.php. Only names generated by ImageService are accepted.
// The website has no session, so these responses carry no no-cache headers and stay cached.

use App\Services\ImageService;

require __DIR__ . '/boot.php';

$name = $_GET['f'] ?? '';
$path = is_string($name) ? (new ImageService())->path($name) : null;
if ($path === null) {
    http_response_code(404);
    exit;
}

// File names are random and never reused, so browsers may cache them forever.
header('Content-Type: image/webp');
header('Content-Length: ' . filesize($path));
header('Cache-Control: public, max-age=31536000, immutable');
readfile($path);
